package cc.nkbr.lanzouplus;

import android.app.AlertDialog;
import android.content.Intent;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;

/** Independent, locally saved repository workspace; one row represents one project. */
final class MarketProjects {
  private final MainActivity owner;
  private final File directory;
  MarketProjects(MainActivity owner){this.owner=owner;directory=new File(owner.getFilesDir(),"market-projects");}
  void show(){
    owner.primaryBase(1);owner.pageKind=6;owner.activeSource=null;owner.clearFolderTrail();owner.systemBackAction=owner::showSources;owner.primaryHeader("lzpmarket 仓库工程");
    ImageButton back=owner.iconButton(R.drawable.ic_back,"返回列表");back.setOnClickListener(v->owner.showSources());owner.pageHeaderRow.addView(back,0,new LinearLayout.LayoutParams(owner.dp(44),owner.dp(48)));
    ImageButton add=owner.iconButton(R.drawable.ic_add,"创建仓库工程"),importProject=owner.iconButton(R.drawable.ic_folder,"导入明文工程");owner.pageHeaderRow.addView(importProject);owner.pageHeaderRow.addView(add);add.setOnClickListener(v->edit(null));importProject.setOnClickListener(v->MarketFilePicker.choose(owner,".json,.lzp-project",this::importProject));
    LinearLayout list=new LinearLayout(owner);list.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(owner);scroll.addView(list);owner.root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));int session=owner.navigationSession;
    owner.io.execute(()->{List<MarketProject> projects=new ArrayList<>();try{File[] files=directory.listFiles((dir,name)->name.endsWith(".json"));if(files!=null)for(File file:files)projects.add(MarketProject.load(file));owner.runOnUiThread(()->{if(session!=owner.navigationSession)return;if(projects.isEmpty())list.addView(owner.text("暂无工程，点击加号选择路径并创建",14,owner.MUTED));for(MarketProject project:projects){LinearLayout row=new LinearLayout(owner);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(owner.dp(10),owner.dp(8),owner.dp(8),owner.dp(8));TextView title=owner.text(project.metadata.optString("title",project.metadata.optString("name"))+"\n"+project.metadata.optString("version")+" · "+project.metadata.optString("publisher"),14,owner.TEXT);row.addView(title,new LinearLayout.LayoutParams(0,-2,1));ImageButton more=owner.iconButton(R.drawable.ic_more,"工程操作");row.addView(more,new LinearLayout.LayoutParams(owner.dp(48),owner.dp(48)));row.setOnClickListener(v->edit(project));more.setOnClickListener(v->actions(project));list.addView(row,new LinearLayout.LayoutParams(-1,owner.dp(72)));}});}catch(Exception error){owner.runOnUiThread(()->owner.showNotice("工程读取失败："+owner.friendlyError(error),true));}});
  }
  private void actions(MarketProject project){AlertDialog prompt=new AlertDialog.Builder(owner).setTitle(project.metadata.optString("title")).setItems(new String[]{"编辑工程","导出明文工程","创建标准仓库压缩包","删除工程"},(dialog,index)->{if(index==0)edit(project);else if(index==1)export(project,false);else if(index==2)export(project,true);else{AlertDialog confirm=new AlertDialog.Builder(owner).setTitle("删除此工程？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{File file=new File(directory,project.id+".json");if(file.delete())show();else owner.showNotice("工程删除失败",true);}).create();owner.showRounded(confirm);}}).create();owner.showRounded(prompt);}

  private void edit(MarketProject existing){
    JSONObject meta=existing==null?new JSONObject():existing.metadata;LinearLayout panel=new LinearLayout(owner);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(owner.dp(18),owner.dp(8),owner.dp(18),owner.dp(8));
    EditText name=input(panel,"仓库名称 lzpmarket-名称",meta.optString("name","lzpmarket-")),title=input(panel,"展示名称",meta.optString("title")),version=input(panel,"版本号",meta.optString("version","1.0.0"));
    Spinner mode=new Spinner(owner);String[] modes={"semantic","date","integer"};mode.setAdapter(new ArrayAdapter<>(owner,android.R.layout.simple_spinner_dropdown_item,modes));for(int i=0;i<modes.length;i++)if(modes[i].equals(meta.optString("versionMode")))mode.setSelection(i);panel.addView(mode,new LinearLayout.LayoutParams(-1,owner.dp(48)));
    EditText publisher=input(panel,"发布者名称",meta.optString("publisher")),description=input(panel,"简介",meta.optString("description")),icon=input(panel,"仓库图标：图片 URL 或本地图片",meta.optString("icon")),avatar=input(panel,"发布者头像：图片 URL 或本地图片",meta.optString("publisherAvatar"));
    Button pickIcon=owner.toolbarTextButton("选择仓库图标"),pickAvatar=owner.toolbarTextButton("选择发布者头像");panel.addView(pickIcon);panel.addView(pickAvatar);pickIcon.setOnClickListener(v->MarketFilePicker.choose(owner,".png,.jpg,.jpeg,.webp,.gif",file->icon.setText(file.getAbsolutePath())));pickAvatar.setOnClickListener(v->MarketFilePicker.choose(owner,".png,.jpg,.jpeg,.webp,.gif",file->avatar.setText(file.getAbsolutePath())));
    EditText readme=input(panel,"README（Markdown）",existing==null?"":existing.readme);readme.setSingleLine(false);readme.setMinLines(4);readme.setMaxLines(8);Button addImage=owner.toolbarTextButton("在 README 添加图片");panel.addView(addImage);addImage.setOnClickListener(v->MarketFilePicker.choose(owner,".png,.jpg,.jpeg,.webp,.gif",file->readme.append("\n![图片]("+file.getAbsolutePath()+")\n")));
    List<SourceDestinationPopup.Destination> paths=new ArrayList<>();Button choose=owner.toolbarTextButton(existing==null?"选择打包源路径（可多选）":"重新选择打包源路径");panel.addView(choose);choose.setOnClickListener(v->owner.io.execute(()->{try{List<Models.Source> values=owner.core.knownCategorySources();owner.runOnUiThread(()->SourceDestinationPopup.select(owner,new SourcePathCatalog(owner,values),selected->{paths.clear();paths.addAll(selected);choose.setText("已选 "+paths.size()+" 个路径");}));}catch(Exception error){owner.runOnUiThread(()->owner.showNotice(owner.friendlyError(error),true));}}));
    AlertDialog prompt=new AlertDialog.Builder(owner).setTitle(existing==null?"创建仓库工程":"编辑仓库工程").setView(owner.limitedDialogScroll(panel,480)).setNegativeButton("取消",null).setPositiveButton("保存工程",null).create();prompt.setOnShowListener(dialog->prompt.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
      if(existing==null&&paths.isEmpty()){choose.setError("请先选择打包路径");return;}
      String draftName=name.getText().toString().trim(),draftTitle=title.getText().toString().trim(),draftVersion=version.getText().toString().trim(),draftPublisher=publisher.getText().toString().trim(),draftDescription=description.getText().toString(),draftIcon=icon.getText().toString().trim(),draftAvatar=avatar.getText().toString().trim(),draftReadme=readme.getText().toString(),draftMode=(String)mode.getSelectedItem();
      Button action=prompt.getButton(AlertDialog.BUTTON_POSITIVE);action.setEnabled(false);action.setText("正在保存图片与工程…");owner.io.execute(()->{try{
        JSONObject metadata=new JSONObject().put("schema",1).put("name",draftName).put("title",draftTitle.isEmpty()?draftName:draftTitle).put("version",draftVersion).put("versionMode",draftMode).put("publisher",draftPublisher).put("publisherAvatar",draftAvatar).put("description",draftDescription).put("icon",draftIcon).put("readme","README.md").put("sources","sources.lzp").put("categories",meta.optJSONArray("categories")==null?new JSONArray():meta.getJSONArray("categories"));
        String sources=paths.isEmpty()?existing.sourceJson:LanzouCore.sourceDocument(SourcePathCatalog.selectedSources(owner.core,paths)).toString();MarketProject project;
        if(existing==null)project=MarketProject.create(metadata,sources,draftReadme);else{project=MarketProject.parse(existing.exportPlain());for(java.util.Iterator<String> keys=metadata.keys();keys.hasNext();){String key=keys.next();project.metadata.put(key,metadata.get(key));}project.sourceJson=sources;project.readme=draftReadme;}
        if(!paths.isEmpty()){while(project.sourcePaths.length()>0)project.sourcePaths.remove(0);for(SourceDestinationPopup.Destination path:paths)project.addSourcePath(path.categoryOnly()?new JSONObject().put("category",path.category).toString():new JSONObject().put("sourceId",LanzouCore.sourceId(path.composite)).put("nodeId",path.nodeId).toString());}
        project.resolveAssets(this::assetBytes);if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("无法创建工程目录");project.save(new File(directory,project.id+".json"));owner.runOnUiThread(()->{prompt.dismiss();owner.showNotice("工程已保存",false);show();});
      }catch(Exception error){owner.runOnUiThread(()->{action.setEnabled(true);action.setText("保存工程");owner.showNotice(owner.friendlyError(error),true);});}});
    }));owner.showRounded(prompt);
  }
  private EditText input(LinearLayout panel,String hint,String value){EditText input=owner.sourceInput(hint,android.text.InputType.TYPE_CLASS_TEXT);input.setText(value);panel.addView(input,new LinearLayout.LayoutParams(-1,owner.dp(56)));return input;}
  private byte[] assetBytes(String reference)throws Exception{if(reference.startsWith("https://"))return MarketRepositoryClient.httpGet(reference,8*1024*1024);try(InputStream input=new FileInputStream(reference)){return MarketRepositoryClient.bytes(input,8*1024*1024);}}
  private void importProject(File file){owner.io.execute(()->{try{MarketProject project=MarketProject.load(file);if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("无法创建工程目录");project.save(new File(directory,project.id+".json"));owner.runOnUiThread(()->{owner.showNotice("已导入明文工程",false);show();});}catch(Exception error){owner.runOnUiThread(()->owner.showNotice("导入失败："+owner.friendlyError(error),true));}});}
  private void export(MarketProject project,boolean publish){owner.showNotice(publish?"正在创建标准仓库压缩包…":"正在导出工程…",false);owner.io.execute(()->{try{
    File folder=new File(owner.getFilesDir(),"project-exports");if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("无法创建导出目录");String name=project.metadata.getString("name")+(publish?"-"+project.metadata.getString("version")+".zip":".lzp-project.json");File file=new File(folder,name);byte[] bytes=publish?project.buildRepositoryZip(this::assetBytes):project.exportPlain();try(OutputStream output=new FileOutputStream(file)){output.write(bytes);}owner.runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType(publish?"application/zip":"application/json");intent.putExtra(Intent.EXTRA_STREAM,new Uri.Builder().scheme("content").authority(owner.getPackageName()+".downloads").appendPath("project").appendPath(file.getName()).build());intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);owner.startActivity(intent);owner.showNotice("导出完成 · "+owner.formatSize(bytes.length),false);});
  }catch(Exception error){owner.runOnUiThread(()->owner.showNotice("导出失败："+owner.friendlyError(error),true));}});}
}
